 * 面板对话框里点击触发，没有其它触发路径；所有路由只服务已注册工作区。
 */
import { realpath, readFile, stat, mkdir, writeFile, rm } from 'node:fs/promises'
import { connect } from 'node:net'
import { homedir } from 'node:os'
